using Avalonia;
using Avalonia.Controls;
using Avalonia.Layout;
using Avalonia.Media;
using Avalonia.Controls.Templates;
namespace ProjectDesk;

public sealed class AiConnectionEditor : Window {
 private CancellationTokenSource? _operation;
 public AiConnectionEditor(AiConnectionProfile original,AiSettingsStore store,IMcpSecrets secrets){Title="AI Connection Settings";Width=690;Height=650;MinWidth=540;MinHeight=450;WindowStartupLocation=WindowStartupLocation.CenterOwner;
  var root=new DockPanel{Margin=new Thickness(22)};var body=new StackPanel{Spacing=14};body.Children.Add(new TextBlock{Text=original.ProviderName,FontSize=24,FontWeight=FontWeight.SemiBold});var modes=original.Provider==AiProvider.OpenAI?new[]{AiConnectionMode.Api,AiConnectionMode.CodexSubscription,AiConnectionMode.Browser}:new[]{AiConnectionMode.Api,AiConnectionMode.Browser};var mode=new ComboBox{Name="AiMode",ItemsSource=modes,SelectedItem=original.Mode,HorizontalAlignment=HorizontalAlignment.Stretch,ItemTemplate=new FuncDataTemplate<AiConnectionMode>((value,_)=>new TextBlock{Text=value switch{AiConnectionMode.Api=>"API key · in-app chat",AiConnectionMode.CodexSubscription=>"ChatGPT subscription · official Codex",_=>"Web subscription · browser handoff"}})};var labels=new TextBlock{Text="Choose direct API chat or your subscription workflow.",TextWrapping=TextWrapping.Wrap,Foreground=DesignTokens.Secondary};
  void Field(string label,Control control,Panel parent){var group=new StackPanel{Spacing=5};group.Children.Add(new TextBlock{Text=label,FontWeight=FontWeight.SemiBold});group.Children.Add(control);Avalonia.Automation.AutomationProperties.SetName(control,label);parent.Children.Add(group);}Field("Connection method",mode,body);body.Children.Add(labels);
  var key=new TextBox{Name="AiApiKey",PasswordChar='●',Text=secrets.Read(original.Id,"AiApiKey"),Watermark="Your own provider API key"};var model=new TextBox{Name="AiModel",Text=original.Model,Watermark="Text model ID; refresh the list or enter one"};var models=new ComboBox{Name="AiModels",HorizontalAlignment=HorizontalAlignment.Stretch};models.SelectionChanged+=(_,_)=>{if(models.SelectedItem is string id)model.Text=id;};
  var api=new StackPanel{Spacing=12};Field("API key",key,api);var refresh=new Button{Content="Refresh Models"};api.Children.Add(refresh);api.Children.Add(models);api.Children.Add(new TextBlock{Text="API usage is billed by the provider. A chat subscription is not an API key. Keys are stored in "+McpCredentialStore.Vault+".",TextWrapping=TextWrapping.Wrap,Foreground=DesignTokens.Secondary});body.Children.Add(api);Field("Model (optional for Codex; required for API)",model,body);
  var executable=new TextBox{Name="AiCodexExecutable",Text=original.Executable??AiCodexClient.FindExecutable(),Watermark="Absolute path to native "+AiCodexClient.ExecutableName};var codex=new StackPanel{Spacing=12};Field("Official Codex executable",executable,codex);var signIn=new Button{Content="Sign In with ChatGPT"};codex.Children.Add(signIn);codex.Children.Add(new TextBlock{Text="Sign in through the official Codex CLI. Planora checks that it is a ChatGPT login before a request. Requests run in a separate empty folder with a read-only sandbox and local tools disabled.",TextWrapping=TextWrapping.Wrap,Foreground=DesignTokens.Secondary});body.Children.Add(codex);
  var web=new StackPanel{Spacing=12};web.Children.Add(new TextBlock{Text=original.Provider==AiProvider.OpenAI?"Use your ChatGPT web subscription. Planora copies a reviewed prompt and opens ChatGPT; paste the answer back to import a task draft.":"Use your Claude subscription. Planora copies a reviewed prompt and opens claude.ai; paste the answer back to import a task draft.",TextWrapping=TextWrapping.Wrap,Foreground=DesignTokens.Secondary});
  // A Claude subscription signs in through Claude Code only; Planora connects to Claude Code instead of embedding that login.
  if(original.Provider==AiProvider.Anthropic){var claudeCode=new Button{Content="Connect Claude Code…"};claudeCode.Click+=async(_,_)=>{for(var owner=Owner as Window;owner!=null;owner=owner.Owner as Window)if(owner is PlannerWindow planner){await new ClaudeCodeWindow(planner).ShowDialog(this);return;}};web.Children.Add(new TextBlock{Text="To let Claude work directly on this project with your subscription, connect Claude Code. Claude Code keeps your Claude sign-in; Planora asks you to approve every change it proposes.",TextWrapping=TextWrapping.Wrap,Foreground=DesignTokens.Secondary});web.Children.Add(claudeCode);}
  body.Children.Add(web);
  var footer=new StackPanel{Spacing=8,Margin=new Thickness(0,12,0,0)};var status=new TextBlock{TextWrapping=TextWrapping.Wrap};footer.Children.Add(status);var actions=new StackPanel{Orientation=Orientation.Horizontal,Spacing=8,HorizontalAlignment=HorizontalAlignment.Right};var forget=new Button{Content="Forget API Key"};forget.Click+=(_,_)=>{secrets.Remove(original.Id,"AiApiKey");key.Text="";status.Text="API key removed.";};var cancel=new Button{Content="Cancel"};cancel.Click+=(_,_)=>Close(null);var save=new Button{Content="Save Connection"};save.Classes.Add("primary");actions.Children.Add(forget);actions.Children.Add(cancel);actions.Children.Add(save);footer.Children.Add(actions);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);root.Children.Add(new ScrollViewer{Content=body});Content=root;
  void Update(){var selected=(AiConnectionMode)mode.SelectedItem!;api.IsVisible=selected==AiConnectionMode.Api;codex.IsVisible=selected==AiConnectionMode.CodexSubscription;web.IsVisible=selected==AiConnectionMode.Browser;model.IsEnabled=selected!=AiConnectionMode.Browser;}mode.SelectionChanged+=(_,_)=>Update();Update();
  refresh.Click+=async(_,_)=>{if(_operation!=null)return;using var stop=new CancellationTokenSource(TimeSpan.FromSeconds(30));_operation=stop;refresh.IsEnabled=save.IsEnabled=false;status.Text="Loading models…";try{using var client=new AiProviderClient(new InputSecret(original.Id,()=>key.Text));var values=await client.ListModelsAsync(original with{Mode=AiConnectionMode.Api},stop.Token);models.ItemsSource=values;status.Text=$"{values.Count} advertised models. Choose one that supports text responses.";}catch(OperationCanceledException){status.Text="Model lookup canceled.";}catch(Exception e){status.Text=e.Message;}finally{_operation=null;refresh.IsEnabled=save.IsEnabled=true;}};
  signIn.Click+=async(_,_)=>{if(_operation!=null)return;using var stop=new CancellationTokenSource(TimeSpan.FromMinutes(3));_operation=stop;signIn.IsEnabled=save.IsEnabled=false;status.Text="Complete ChatGPT sign-in in the browser opened by Codex.";try{await new AiCodexClient().LoginAsync(executable.Text?.Trim()??"",stop.Token);status.Text="Codex sign-in completed. Save Connection to use it.";}catch(OperationCanceledException){status.Text="Sign-in canceled.";}catch(Exception e){status.Text=e.Message;}finally{_operation=null;signIn.IsEnabled=save.IsEnabled=true;}};
  save.Click+=(_,_)=>{try{var profile=original with{Mode=(AiConnectionMode)mode.SelectedItem!,Model=model.Text?.Trim()??"",Executable=string.IsNullOrWhiteSpace(executable.Text)?null:executable.Text.Trim()};profile.Validate(profile.Mode!=AiConnectionMode.Browser);if(profile.Mode==AiConnectionMode.Api){if(string.IsNullOrWhiteSpace(key.Text)||key.Text.Any(char.IsControl))throw new ArgumentException("Enter a valid API key.");secrets.Write(profile.Id,"AiApiKey",key.Text.Trim());}store.Save(profile);Close(profile);}catch(Exception e){status.Text=e.Message;}};Closing+=(_,_)=>_operation?.Cancel();
 }
 private sealed class InputSecret(string id,Func<string?> read):IMcpSecrets {public string? Read(string target,string name)=>target==id&&name=="AiApiKey"?read():null;public void Write(string id,string name,string value)=>throw new NotSupportedException();public void Remove(string id,string name)=>throw new NotSupportedException();}
}
